 UNION ALL SELECT jsonb_build_object('kind','membership','role',pg_get_userbyid(roleid),'member',pg_get_userbyid(member),'admin',admin_option,'inherit',inherit_option,'set',set_option)FROM pg_auth_members WHERE roleid IN(SELECT oid FROM pg_roles WHERE rolname IN('ws_owner','ws_runtime','ws_authz_reader','supabase_auth_admin'))OR member IN(SELECT oid FROM pg_roles WHERE rolname IN('ws_owner','ws_runtime','ws_authz_reader','supabase_auth_admin'))
 )q));END$bind$;RESET ROLE;COMMIT;
